import{_ as t,o,c as i,a5 as l}from"./chunks/framework.CsGesDJn.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-5-update-agency-profile/report3_spec.md","filePath":"feature/agency-workspace/3-4-5-update-agency-profile/report3_spec.md"}'),s={name:"feature/agency-workspace/3-4-5-update-agency-profile/report3_spec.md"};function r(n,e,a,g,d,p){return o(),i("div",null,[...e[0]||(e[0]=[l("<p><strong>3.4.5 Update Agency Profile</strong></p><p><strong>Function Trigger</strong></p><p>The Owner of an Agency opens the Agency Profile in edit mode (/agencies/:agencyId/profile/edit), changes one or more fields and submits the form, or uploads a new logo file while on that screen.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner.</li><li><strong>Purpose</strong>: Let the Owner keep the Agency profile up to date — name, branding and company information.</li><li><strong>Interface</strong>: Edit Agency Profile page — the same field set as the Create Agency form, pre-filled with current values, plus a logo picker that uploads a new logo file.</li><li><strong>Data Processing</strong>: The system loads the Agency, confirms the caller is its Owner, validates the submitted values, then replaces the stored profile with the submitted values in full — every field not sent is cleared. The logo is uploaded separately and the system fills in the logo location.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Edit Agency Profile page:</p><ul><li>The full field set of the Agency profile, pre-filled from current values, name marked required.</li><li>A logo picker; the chosen file is uploaded separately from the form.</li><li>A save action; on success the user stays on the screen and sees the refreshed values.</li><li>Because save replaces the whole profile, every field that must survive has to be present when submitted.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: name of the Agency.</li><li><strong>Input optional</strong>: logoUrl, description, category, companySize, website, phone, location, brandColor (hex, max 9 chars), logoIcon, tagline (max 140 chars), foundedYear, facebookUrl, linkedinUrl, instagramUrl. The logo file itself goes through the separate logo upload.</li><li><strong>System data</strong>: the Agency record — id, name, ownerId, logoUrl, description, category, companySize, website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, status, createdAt, updatedAt — and the Owner identifier used for the access check.</li><li><strong>Output</strong>: the updated profile. After a logo upload, the same profile with the new logo location and a refreshed update timestamp.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-25 (analogous)</strong>: updating the Agency profile is Owner-only, mirroring the rule that workspace settings can only be updated by an authorized role. Anybody else is refused with 403 NOT_AGENCY_OWNER.</li><li>The save replaces the whole profile rather than patching individual fields: a field not sent is cleared. The client must send back every current value, including unchanged ones.</li><li>Name is mandatory; an empty name is refused with 400 VALIDATION_ERROR.</li><li>The logo is uploaded as a file through the Agency logo upload, not through the logo URL field of the form.</li><li>A logo file that cannot be read is refused with 400 FILE_READ_ERROR; the stored profile stays untouched.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller is not the Agency Owner → Display: <strong>MSG39</strong></li><li>Name empty → Display: <strong>MSG02</strong></li><li>Agency does not exist → Display: <strong>MSG38</strong></li><li>Logo upload by a caller who is not the Agency Owner → Display: <strong>MSG39</strong></li><li>Logo file cannot be read → Display: <strong>MSG29</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The Owner opens the Agency Profile in edit mode; the form loads with current values.</li><li>The Owner changes the fields that need updating and leaves the rest as they are.</li><li>The client submits the full profile.</li><li>The system loads the Agency by its identifier and confirms the caller is its Owner.</li><li>The system validates the submitted values against the rules above.</li><li>The system replaces the stored profile with the submitted values and returns the updated profile; toast <strong>MSG26</strong>.</li><li>The Owner optionally picks a new logo file; the system stores the file, fills in the logo, and returns the updated profile; toast <strong>MSG94</strong>.</li><li>The client shows a confirmation and refreshes the form and logo preview.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>4.a1: Agency does not exist → 404 AGENCY_NOT_FOUND, toast <strong>MSG38</strong>. 4.a2: The Owner returns to the Agency list.</li><li>4.b1: Caller is not the Agency Owner → 403 NOT_AGENCY_OWNER, toast <strong>MSG39</strong>; nothing is changed. 4.b2: The caller returns to the Agency list.</li><li>5.a1: Name left empty → 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>; nothing is changed. 5.a2: The Owner fills in the name and resubmits.</li><li>7.a1: Logo file cannot be read → 400 FILE_READ_ERROR, toast <strong>MSG29</strong>; the profile keeps its previous values. 7.a2: The Owner selects a valid file and retries.</li><li>3.a1: A field the form fails to send back is cleared, because save replaces the whole profile — expected behaviour, not an error. 3.a2: The Owner reviews the saved profile and resubmits any field found missing.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The profile carries the submitted values and a refreshed update timestamp.</li><li>After a logo upload, the profile carries the new logo location and a refreshed update timestamp.</li></ul>",14)])])}const u=t(s,[["render",r]]);export{c as __pageData,u as default};
